/// Kind of Koopa IR value.
#[derive(Clone, Debug)]
pub enum ValueKind {
  /// Integer constant.
  Integer(values::Integer),
  /// Zero initializer.
  ZeroInit(values::ZeroInit),
  /// Undefined value.
  Undef(values::Undef),
  /// Aggregate constant.
  Aggregate(values::Aggregate),
  /// Function argument reference.
  FuncArgRef(values::FuncArgRef),
  /// Basic block argument reference.
  BlockArgRef(values::BlockArgRef),
  /// Local memory allocation.
  Alloc(values::Alloc),
  /// Global memory allocation.
  GlobalAlloc(values::GlobalAlloc),
  /// Memory load.
  Load(values::Load),
  /// Memory store.
  Store(values::Store),
  /// Pointer calculation.
  GetPtr(values::GetPtr),
  /// Element pointer calculation.
  GetElemPtr(values::GetElemPtr),
  /// Binary operation.
  Binary(values::Binary),
  /// Conditional branch.
  Branch(values::Branch),
  /// Unconditional jump.
  Jump(values::Jump),
  /// Function call.
  Call(values::Call),
  /// Function return.
  Return(values::Return),
}

impl ValueKind {
  /// Returns an iterator of all values that used by the `ValueKind`.
  pub fn value_uses(&self) -> ValueUses {
    ValueUses {
      kind: self,
      index: 0,
    }
  }

  /// Returns an iterator of all basic blocks that used by the `ValueKind`.
  pub fn bb_uses(&self) -> BasicBlockUses {
    BasicBlockUses {
      kind: self,
      index: 0,
    }
  }

  /// Returns `true` if the `ValueKind` represents a constant value.
  pub fn is_const(&self) -> bool {
    matches!(
      self,
      ValueKind::Integer(..)
        | ValueKind::ZeroInit(..)
        | ValueKind::Undef(..)
        | ValueKind::Aggregate(..)
    )
  }

  /// Returns `true` if the `ValueKind` represents a global allocation.
  pub fn is_global_alloc(&self) -> bool {
    matches!(self, ValueKind::GlobalAlloc(..))
  }

  /// Returns `true` if the `ValueKind` represents a local instruction.
  pub fn is_local_inst(&self) -> bool {
    matches!(
      self,
      ValueKind::Alloc(..)
        | ValueKind::Load(..)
        | ValueKind::Store(..)
        | ValueKind::GetPtr(..)
        | ValueKind::GetElemPtr(..)
        | ValueKind::Binary(..)
        | ValueKind::Branch(..)
        | ValueKind::Jump(..)
        | ValueKind::Call(..)
        | ValueKind::Return(..)
    )
  }
}

/// An iterator over all values that used by a [`ValueKind`].
pub struct ValueUses<'a> {
  kind: &'a ValueKind,
  index: usize,
}

impl<'a> Iterator for ValueUses<'a> {
  type Item = Value;

  fn next(&mut self) -> Option<Self::Item> {
    let cur = self.index;
    self.index += 1;
    macro_rules! vec_use {
      ($vec:expr) => {
        if cur < $vec.len() {
          Some($vec[cur])
        } else {
          None
        }
      };
    }
    macro_rules! field_use {
      ($($field:expr),+) => {
        field_use!(@expand 0 $(,$field)+)
      };
      (@expand $index:expr) => {
        None
      };
      (@expand $index:expr, $head:expr $(,$tail:expr)*) => {
        if cur == $index {
          Some($head)
        } else {
          field_use!(@expand $index + 1 $(,$tail)*)
        }
      };
    }
    match self.kind {
      ValueKind::Aggregate(v) => vec_use!(v.elems()),
      ValueKind::GlobalAlloc(v) => field_use!(v.init()),
      ValueKind::Load(v) => field_use!(v.src()),
      ValueKind::Store(v) => field_use!(v.value(), v.dest()),
      ValueKind::GetPtr(v) => field_use!(v.src(), v.index()),
      ValueKind::GetElemPtr(v) => field_use!(v.src(), v.index()),
      ValueKind::Binary(v) => field_use!(v.lhs(), v.rhs()),
      ValueKind::Branch(v) => {
        let tlen = v.true_args().len();
        if cur == 0 {
          Some(v.cond())
        } else if cur >= 1 && cur <= tlen {
          Some(v.true_args()[cur - 1])
        } else if cur > tlen && cur <= tlen + v.false_args().len() {
          Some(v.false_args()[cur - tlen - 1])
        } else {
          None
        }
      }
      ValueKind::Jump(v) => vec_use!(v.args()),
      ValueKind::Call(v) => vec_use!(v.args()),
      ValueKind::Return(v) => match cur {
        0 => v.value(),
        _ => None,
      },
      _ => None,
    }
  }
}

/// An iterator over all basic blocks that used by a [`ValueKind`].
pub struct BasicBlockUses<'a> {
  kind: &'a ValueKind,
  index: usize,
}

impl<'a> Iterator for BasicBlockUses<'a> {
  type Item = BasicBlock;

  fn next(&mut self) -> Option<Self::Item> {
    let cur = self.index;
    self.index += 1;
    match self.kind {
      ValueKind::Branch(br) => match cur {
        0 => Some(br.true_bb()),
        1 => Some(br.false_bb()),
        _ => None,
      },
      ValueKind::Jump(jump) => match cur {
        0 => Some(jump.target()),
        _ => None,
      },
      _ => None,
    }
  }
}

//! Types of Koopa IR values.
//!
//! Each Koopa IR value and function should have a type. A type can be
//! a 32-bit integer type, a unit type, an array type, a pointer type,
//! or a function type.

use std::cell::{Cell, RefCell};
use std::collections::HashMap;
use std::rc::Rc;
use std::{cmp, fmt, hash, mem};

/// Kind of type.
#[derive(Hash, Clone, PartialEq, Eq)]
pub enum TypeKind {
  /// 32-bit integer.
  Int32,
  /// Unit (void).
  Unit,
  /// Array (with base type and length).
  Array(Type, usize),
  /// Pointer (with base type).
  Pointer(Type),
  /// Function (with parameter types and return type).
  Function(Vec<Type>, Type),
}

impl fmt::Display for TypeKind {
  fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
    match self {
      TypeKind::Int32 => write!(f, "i32"),
      TypeKind::Unit => write!(f, "unit"),
      TypeKind::Array(t, len) => write!(f, "[{}, {}]", t, len),
      TypeKind::Pointer(t) => write!(f, "*{}", t),
      TypeKind::Function(params, ret) => {
        write!(f, "(")?;
        let mut first = true;
        for param in params {
          if !first {
            write!(f, ", ")?;
          }
          write!(f, "{}", param)?;
          first = false;
        }
        if !ret.is_unit() {
          write!(f, "): {}", ret)
        } else {
          write!(f, ")")
        }
      }
    }
  }
}

/// Types of Koopa IR values.
#[derive(Clone, Eq)]
pub struct Type(Rc<TypeKind>);

impl Type {
  thread_local! {
    /// Pool of all created types.
    static POOL: RefCell<HashMap<TypeKind, Type>> = RefCell::new(HashMap::new());

    /// Size of pointers.
    static PTR_SIZE: Cell<usize> = Cell::new(mem::size_of::<*const ()>());
  }

  /// Returns a type by the given [`TypeKind`].
  pub fn get(type_data: TypeKind) -> Type {
    Self::POOL.with(|pool| {
      let mut pool = pool.borrow_mut();
      pool.get(&type_data).cloned().unwrap_or_else(|| {
        let v = Self(Rc::new(type_data.clone()));
        pool.insert(type_data, v.clone());
        v
      })
    })
  }

  /// Returns an `i32` type.
  pub fn get_i32() -> Type {
    Type::get(TypeKind::Int32)
  }

  /// Returns an `unit` type.
  pub fn get_unit() -> Type {
    Type::get(TypeKind::Unit)
  }

  /// Returns an array type.
  pub fn get_array(base: Type, len: usize) -> Type {
    assert!(len != 0, "`len` can not be zero!");
    Type::get(TypeKind::Array(base, len))
  }

  /// Returns an pointer type.
  pub fn get_pointer(base: Type) -> Type {
    Type::get(TypeKind::Pointer(base))
  }

  /// Returns an function type.
  pub fn get_function(params: Vec<Type>, ret: Type) -> Type {
    Type::get(TypeKind::Function(params, ret))
  }

  /// Sets the size of pointers.
  pub fn set_ptr_size(size: usize) {
    Self::PTR_SIZE.with(|ptr_size| ptr_size.set(size));
  }

  /// Returns a reference to the kind of the current type.
  pub fn kind(&self) -> &TypeKind {
    &self.0
  }

  /// Checks if the current type is an integer type.
  pub fn is_i32(&self) -> bool {
    matches!(self.0.as_ref(), TypeKind::Int32)
  }

  /// Checks if the current type is a unit type.
  pub fn is_unit(&self) -> bool {
    matches!(self.0.as_ref(), TypeKind::Unit)
  }

  /// Returns the size of the current type in bytes.
  pub fn size(&self) -> usize {
    match self.kind() {
      TypeKind::Int32 => 4,
      TypeKind::Unit => 0,
      TypeKind::Array(ty, len) => ty.size() * len,
      TypeKind::Pointer(..) | TypeKind::Function(..) => Self::PTR_SIZE.with(|s| s.get()),
    }
  }
}

impl cmp::PartialEq for Type {
  fn eq(&self, other: &Self) -> bool {
    Rc::ptr_eq(&self.0, &other.0)
  }
}

impl fmt::Display for Type {
  fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
    write!(f, "{}", self.0)
  }
}

impl fmt::Debug for Type {
  fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
    write!(f, "{}", self.0)
  }
}

impl hash::Hash for Type {
  fn hash<H: hash::Hasher>(&self, state: &mut H) {
    self.0.hash(state);
  }
}

