//! Build a single component into Koopa IR.

use crate::ast_def::declarations::*;
use koopa::ir::{builder_traits::*, FunctionData, Program, Type, Value};

use super::{
    build_expressions::{IRExpBuildResult, IRExpBuildable},
    build_shape, create_new_local_value, get_array_type, get_valuedata, insert_local_instructions,
    IRBuildResult, IRBuildable, MyIRGeneratorInfo, SymbolTableEntry,
};

fn build_integer_value(
    value: i32,
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    if is_global {
        program.new_value().integer(value)
    } else {
        create_new_local_value(program, my_ir_generator_info).integer(value)
    }
}

fn build_zero_value(
    shape: &[usize],
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    if shape.is_empty() {
        build_integer_value(0, is_global, program, my_ir_generator_info)
    } else {
        let mut elems = Vec::with_capacity(shape[0]);
        for _ in 0..shape[0] {
            elems.push(build_zero_value(
                &shape[1..],
                is_global,
                program,
                my_ir_generator_info,
            ));
        }
        if is_global {
            program.new_value().aggregate(elems)
        } else {
            create_new_local_value(program, my_ir_generator_info).aggregate(elems)
        }
    }
}

fn current_scope_has_symbol(my_ir_generator_info: &MyIRGeneratorInfo, name: &str) -> bool {
    my_ir_generator_info
        .symbol_tables
        .symbol_tables
        .last()
        .unwrap()
        .contains_key(name)
}

fn scalar_value_from_init_result(
    result: IRInitValBuildResult,
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<Value, String> {
    match result {
        IRInitValBuildResult::Const(int) => Ok(build_integer_value(
            int,
            is_global,
            program,
            my_ir_generator_info,
        )),
        IRInitValBuildResult::Var(value) | IRInitValBuildResult::Aggregate(value) => Ok(value),
    }
}

fn scalar_const_from_init_result(
    result: IRInitValBuildResult,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<i32, String> {
    match result {
        IRInitValBuildResult::Const(int) => Ok(int),
        IRInitValBuildResult::Var(_) => Err("Const initializer must be constant. ".to_string()),
        IRInitValBuildResult::Aggregate(value) => match get_valuedata(value, program, my_ir_generator_info)
            .kind()
        {
            koopa::ir::ValueKind::Integer(integer) => Ok(integer.value()),
            _ => Err("Scalar const initializer must evaluate to an integer. ".to_string()),
        },
    }
}

fn array_scalar_count(shape: &[usize]) -> usize {
    if shape.is_empty() {
        1
    } else {
        shape[0] * array_scalar_count(&shape[1..])
    }
}

fn flatten_initvals(
    shape: &[usize],
    childs: &[Box<InitVal>],
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(Vec<IRExpBuildResult>, usize), String> {
    if shape.is_empty() {
        if childs.is_empty() {
            return Ok((vec![IRExpBuildResult::Const(0)], 0));
        }
        return match childs[0].as_ref() {
            InitVal::Exp(exp) => Ok((vec![exp.build(program, my_ir_generator_info)?], 1)),
            InitVal::Aggregate(nested) => {
                if nested.is_empty() {
                    Ok((vec![IRExpBuildResult::Const(0)], 1))
                } else {
                    let (mut values, _) =
                        flatten_initvals(&[], nested, program, my_ir_generator_info)?;
                    if values.is_empty() {
                        values.push(IRExpBuildResult::Const(0));
                    }
                    Ok((vec![values.remove(0)], 1))
                }
            }
        };
    }

    let inner_shape = &shape[1..];
    let inner_scalar_count = array_scalar_count(inner_shape);
    let mut consumed = 0;
    let mut flattened = Vec::with_capacity(shape[0] * inner_scalar_count);
    for _ in 0..shape[0] {
        if consumed >= childs.len() {
            for _ in 0..inner_scalar_count {
                flattened.push(IRExpBuildResult::Const(0));
            }
            continue;
        }

        let (values, used) = match childs[consumed].as_ref() {
            InitVal::Aggregate(nested) => {
                if inner_shape.is_empty() {
                    let (values, _) = flatten_initvals(&[], nested, program, my_ir_generator_info)?;
                    (values, 1)
                } else {
                    let (values, _) =
                        flatten_initvals(inner_shape, nested, program, my_ir_generator_info)?;
                    (values, 1)
                }
            }
            InitVal::Exp(_) => flatten_initvals(
                inner_shape,
                &childs[consumed..],
                program,
                my_ir_generator_info,
            )?,
        };
        flattened.extend(values);
        consumed += used;
    }
    Ok((flattened, consumed))
}

fn linear_index_to_nd_indexes(mut index: usize, shape: &[usize]) -> Vec<usize> {
    let mut result = Vec::with_capacity(shape.len());
    for i in 0..shape.len() {
        let stride = array_scalar_count(&shape[i + 1..]);
        result.push(index / stride);
        index %= stride;
    }
    result
}

fn store_flattened_array_init(
    array_ptr: Value,
    shape: &[usize],
    values: Vec<IRExpBuildResult>,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    for (flat_index, value_result) in values.into_iter().enumerate() {
        let indexes = linear_index_to_nd_indexes(flat_index, shape);
        let mut curr_ptr = array_ptr;
        let mut insts = vec![];
        for index in indexes {
            let index_value =
                create_new_local_value(program, my_ir_generator_info).integer(index as i32);
            let next_ptr =
                create_new_local_value(program, my_ir_generator_info).get_elem_ptr(curr_ptr, index_value);
            insts.push(next_ptr);
            curr_ptr = next_ptr;
        }
        insert_local_instructions(program, my_ir_generator_info, insts);
        let value = match value_result {
            IRExpBuildResult::Const(int) => {
                create_new_local_value(program, my_ir_generator_info).integer(int)
            }
            IRExpBuildResult::Value(value) => value,
        };
        let store = create_new_local_value(program, my_ir_generator_info).store(value, curr_ptr);
        insert_local_instructions(program, my_ir_generator_info, [store]);
    }
    Ok(())
}

impl IRBuildable for FuncDef {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let FuncDef::Default(return_type, ident, params, block) = self;
        if my_ir_generator_info.check_duplicate_global_symbol(&ident.content) {
            return Err(format!("Duplicate global function symbol: {}", ident.content));
        }

        let mut param_entries = Vec::with_capacity(params.len());
        for param in params {
            let FuncFParam::Default(btype, param_ident, shape) = param;
            let param_type = match shape {
                None => Type::get(btype.content.clone()),
                Some(shape_exps) => {
                    let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
                    Type::get_pointer(Type::get(get_array_type(btype, &shape)))
                }
            };
            param_entries.push((Some(format!("%{}_param", param_ident.content)), param_type));
        }

        let function = program.new_func(FunctionData::with_param_names(
            format!("@{}", ident.content),
            param_entries,
            Type::get(return_type.content.clone()),
        ));
        my_ir_generator_info
            .function_table
            .insert(ident.content.clone(), function);
        my_ir_generator_info.curr_func = Some(function);
        my_ir_generator_info.curr_block = Some(program.func_mut(function).dfg_mut().new_bb().basic_block(None));
        program
            .func_mut(function)
            .layout_mut()
            .bbs_mut()
            .push_key_back(my_ir_generator_info.curr_block.unwrap());

        my_ir_generator_info.symbol_tables.add_new_table();
        for (param_def, param_value) in params.iter().zip(program.func(function).params().iter().copied()) {
            let FuncFParam::Default(btype, param_ident, shape) = param_def;
            if current_scope_has_symbol(my_ir_generator_info, &param_ident.content) {
                return Err(format!("Duplicate parameter symbol: {}", param_ident.content));
            }
            let param_typekind = match shape {
                None => btype.content.clone(),
                Some(shape_exps) => {
                    let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
                    koopa::ir::TypeKind::Pointer(Type::get(get_array_type(btype, &shape)))
                }
            };
            let alloc = create_new_local_value(program, my_ir_generator_info)
                .alloc(Type::get(param_typekind.clone()));
            program
                .func_mut(function)
                .dfg_mut()
                .set_value_name(alloc, Some(format!("@{}", param_ident.content)));
            let store = create_new_local_value(program, my_ir_generator_info).store(param_value, alloc);
            insert_local_instructions(program, my_ir_generator_info, [alloc, store]);
            my_ir_generator_info.symbol_tables.insert(
                param_ident.content.clone(),
                SymbolTableEntry::Variable(param_typekind, alloc),
            );
        }

        let block_result = block.build(program, my_ir_generator_info)?;
        if matches!(block_result, IRBuildResult::OK) {
            let ret_inst = if return_type.content.is_unit() {
                create_new_local_value(program, my_ir_generator_info).ret(None)
            } else {
                let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                create_new_local_value(program, my_ir_generator_info).ret(Some(zero))
            };
            insert_local_instructions(program, my_ir_generator_info, [ret_inst]);
        }

        my_ir_generator_info.curr_block = None;
        my_ir_generator_info.curr_func = None;
        Ok(IRBuildResult::OK)
    }
}

impl IRBuildable for Block {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let Block::Default(stmts) = self;
        let mut block_result = IRBuildResult::OK;
        for stmt in stmts {
            let result = stmt.build(program, my_ir_generator_info)?;
            // Ignore everything after the return statement.
            if let IRBuildResult::EARLYSTOPPING = result {
                block_result = result;
                break;
            }
        }
        my_ir_generator_info.symbol_tables.delete_new_table();
        Ok(block_result)
    }
}

impl IRBuildable for BlockItem {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            BlockItem::Decl(decl) => decl.build(program, my_ir_generator_info),
            BlockItem::Stmt(stmt) => stmt.build(program, my_ir_generator_info),

            BlockItem::Stmt(stmt) => stmt.build(program, my_ir_generator_info),
        }
    }
}

pub enum IRInitValBuildResult {
    Const(i32),
    Var(Value),
    Aggregate(Value),
}

fn build_new_aggregate(
    shape: &[usize],
    childs: &[Box<InitVal>],
    is_global: bool,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(Value, usize), String> {
    if shape.is_empty() {
        if childs.is_empty() {
            return Ok((build_zero_value(&[], is_global, program, my_ir_generator_info), 0));
        }
        return match childs[0].as_ref() {
            InitVal::Exp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok((
                    build_integer_value(int, is_global, program, my_ir_generator_info),
                    1,
                )),
                IRExpBuildResult::Value(value) => {
                    if is_global {
                        Err("Global aggregate initializer must be constant. ".to_string())
                    } else {
                        Ok((value, 1))
                    }
                }
            },
            InitVal::Aggregate(nested) => {
                if nested.is_empty() {
                    Ok((build_zero_value(&[], is_global, program, my_ir_generator_info), 1))
                } else {
                    let (value, _) =
                        build_new_aggregate(&[], nested, is_global, program, my_ir_generator_info)?;
                    Ok((value, 1))
                }
            }
        };
    }

    let inner_shape = &shape[1..];
    let mut consumed = 0;
    let mut elems = Vec::with_capacity(shape[0]);
    for _ in 0..shape[0] {
        if consumed >= childs.len() {
            elems.push(build_zero_value(
                inner_shape,
                is_global,
                program,
                my_ir_generator_info,
            ));
            continue;
        }
        let (value, used) = match childs[consumed].as_ref() {
            InitVal::Aggregate(nested) => {
                if inner_shape.is_empty() {
                    let (value, _) =
                        build_new_aggregate(&[], nested, is_global, program, my_ir_generator_info)?;
                    (value, 1)
                } else {
                    let (value, _) = build_new_aggregate(
                        inner_shape,
                        nested,
                        is_global,
                        program,
                        my_ir_generator_info,
                    )?;
                    (value, 1)
                }
            }
            InitVal::Exp(_) => build_new_aggregate(
                inner_shape,
                &childs[consumed..],
                is_global,
                program,
                my_ir_generator_info,
            )?,
        };
        elems.push(value);
        consumed += used;
    }

    if !elems
        .iter()
        .all(|value| get_valuedata(*value, program, my_ir_generator_info).kind().is_const())
    {
        return Err("Aggregate value contains non-constant elements. ".to_string());
    }

    let aggregate = if is_global {
        program.new_value().aggregate(elems)
    } else {
        create_new_local_value(program, my_ir_generator_info).aggregate(elems)
    };
    Ok((aggregate, consumed))
}

fn aggregate_to_store_insts(
    aggr: Value,
    aggr_ptr: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<(), String> {
    match get_valuedata(aggr, program, my_ir_generator_info).kind() {
        koopa::ir::ValueKind::Integer(_) => {
            let store = create_new_local_value(program, my_ir_generator_info).store(aggr, aggr_ptr);
            insert_local_instructions(program, my_ir_generator_info, [store]);
            Ok(())
        }
        koopa::ir::ValueKind::Aggregate(aggregate) => {
            let elems = aggregate.elems().to_vec();
            for (index, elem) in elems.into_iter().enumerate() {
                let index_value =
                    create_new_local_value(program, my_ir_generator_info).integer(index as i32);
                let elem_ptr = create_new_local_value(program, my_ir_generator_info)
                    .get_elem_ptr(aggr_ptr, index_value);
                insert_local_instructions(program, my_ir_generator_info, [elem_ptr]);
                aggregate_to_store_insts(elem, elem_ptr, program, my_ir_generator_info)?;
            }
            Ok(())
        }
        _ => Err("Local aggregate initializer must be a constant aggregate. ".to_string()),
    }
}

impl InitVal {
    fn build(
        &self,
        shape: &[usize],
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRInitValBuildResult, String> {
        let is_global = my_ir_generator_info.curr_func.is_none();
        match self {
            InitVal::Exp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok(IRInitValBuildResult::Const(int)),
                IRExpBuildResult::Value(value) => {
                    if is_global {
                        Err(format!(
                            "Non-constant expression '{:?}' in global variable initval: {:?}",
                            exp, self
                        ))
                    } else {
                        Ok(IRInitValBuildResult::Var(value))
                    }
                }
            },
            InitVal::Aggregate(childs) => {
                let (value, _) =
                    build_new_aggregate(shape, childs, is_global, program, my_ir_generator_info)?;
                Ok(IRInitValBuildResult::Aggregate(value))
            }
        }
    }
}

impl IRBuildable for Decl {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            Decl::ConstDecl(const_decl) => const_decl.build(program, my_ir_generator_info),
            Decl::VarDecl(var_decl) => var_decl.build(program, my_ir_generator_info),
        }
    }
}

impl IRBuildable for ConstDecl {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let ConstDecl::Default(btype, defs) = self;
        let is_global = my_ir_generator_info.curr_func.is_none();
        for def in defs {
            let ConstDef::Default(ident, shape_exps, initval) = def;
            let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
            if is_global {
                if my_ir_generator_info.check_duplicate_global_symbol(&ident.content) {
                    return Err(format!("Duplicate global symbol: {}", ident.content));
                }
            } else if current_scope_has_symbol(my_ir_generator_info, &ident.content) {
                return Err(format!("Duplicate local symbol: {}", ident.content));
            }

            if shape.is_empty() {
                let const_value = scalar_const_from_init_result(
                    initval.build(&shape, program, my_ir_generator_info)?,
                    program,
                    my_ir_generator_info,

                    my_ir_generator_info,
                )?;
                my_ir_generator_info.symbol_tables.insert(
                    ident.content.clone(),
                    SymbolTableEntry::Constant(btype.content.clone(), const_value),
                );
                continue;
            }

            let const_typekind = get_array_type(btype, &shape);
            let const_type = Type::get(const_typekind.clone());
            let init_value = match initval.build(&shape, program, my_ir_generator_info)? {
                IRInitValBuildResult::Aggregate(value) => value,
                _ => return Err("Array const initializer must be an aggregate. ".to_string()),
            };
            if is_global {
                let global_alloc = program.new_value().global_alloc(init_value);
                program.set_value_name(global_alloc, Some(format!("@{}", ident.content)));
                my_ir_generator_info.symbol_tables.insert(
                    ident.content.clone(),
                    SymbolTableEntry::Variable(const_typekind, global_alloc),
                );
            } else {
                let alloc = create_new_local_value(program, my_ir_generator_info).alloc(const_type);
                program
                    .func_mut(my_ir_generator_info.curr_func.unwrap())
                    .dfg_mut()
                    .set_value_name(alloc, Some(format!("@{}", ident.content)));
                insert_local_instructions(program, my_ir_generator_info, [alloc]);
                aggregate_to_store_insts(init_value, alloc, program, my_ir_generator_info)?;
                my_ir_generator_info.symbol_tables.insert(
                    ident.content.clone(),
                    SymbolTableEntry::Variable(const_typekind, alloc),
                );
            }
        }
        Ok(IRBuildResult::OK)
    }
}

impl IRBuildable for VarDecl {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        let VarDecl::Default(btype, defs) = self;
        let is_global = my_ir_generator_info.curr_func.is_none();
        for def in defs {
            let VarDef::Default(ident, shape_exps, initval) = def;
            let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
            let var_typekind = get_array_type(btype, &shape);
            let var_type = Type::get(var_typekind.clone());

            if is_global {
                if my_ir_generator_info.check_duplicate_global_symbol(&ident.content) {
                    return Err(format!("Duplicate global symbol: {}", ident.content));
                }
            } else if current_scope_has_symbol(my_ir_generator_info, &ident.content) {
                return Err(format!("Duplicate local symbol: {}", ident.content));
            }

            if is_global {
                let init_value = match initval {
                    None => program.new_value().zero_init(var_type.clone()),
                    Some(init) if shape.is_empty() => scalar_value_from_init_result(
                        init.build(&shape, program, my_ir_generator_info)?,
                        true,
                        program,
                        my_ir_generator_info,
                    )?,
                    Some(init) => match init.build(&shape, program, my_ir_generator_info)? {
                        IRInitValBuildResult::Aggregate(value) => value,
                        _ => return Err("Array initializer must be an aggregate. ".to_string()),
                    },
                };
                let global_alloc = program.new_value().global_alloc(init_value);
                program.set_value_name(global_alloc, Some(format!("@{}", ident.content)));
                my_ir_generator_info.symbol_tables.insert(
                    ident.content.clone(),
                    SymbolTableEntry::Variable(var_typekind, global_alloc),
                );
                continue;
            }

            let alloc = create_new_local_value(program, my_ir_generator_info).alloc(var_type);
            program
                .func_mut(my_ir_generator_info.curr_func.unwrap())
                .dfg_mut()
                .set_value_name(alloc, Some(format!("@{}", ident.content)));
            insert_local_instructions(program, my_ir_generator_info, [alloc]);
            my_ir_generator_info.symbol_tables.insert(
                ident.content.clone(),
                SymbolTableEntry::Variable(var_typekind, alloc),
            );

            if let Some(init) = initval {
                if shape.is_empty() {
                    let value = scalar_value_from_init_result(
                        init.build(&shape, program, my_ir_generator_info)?,
                        false,
                        program,
                        my_ir_generator_info,
                    )?;
                    let store = create_new_local_value(program, my_ir_generator_info).store(value, alloc);
                    insert_local_instructions(program, my_ir_generator_info, [store]);
                } else {
                    let InitVal::Aggregate(childs) = init else {
                        return Err("Array initializer must be an aggregate. ".to_string());
                    };
                    let (flattened, _) =
                        flatten_initvals(&shape, childs, program, my_ir_generator_info)?;
                    store_flattened_array_init(
                        alloc,
                        &shape,
                        flattened,
                        program,
                        my_ir_generator_info,
                    )?;
                }
            }
        }
        Ok(IRBuildResult::OK)
    }
}

