//! Build a single component into Koopa IR.

use crate::ast_def::expressions::*;
use koopa::ir::{builder_traits::*, Program, Type, TypeKind, Value};

use super::{
    create_new_block, create_new_local_value, get_valuedata,
    insert_basic_blocks, insert_local_instructions, MyIRGeneratorInfo, SymbolTableEntry,
};

/// IR expression building result. If the expression is a constant expression, returns the i32 result.
/// Otherwise, returns the Koopa IR Value.
pub enum IRExpBuildResult {
    Const(i32),
    Value(Value),
}
pub trait IRExpBuildable {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String>;
}

impl IRExpBuildable for Exp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            Exp::LOrExp(lor_exp) => lor_exp.build(program, my_ir_generator_info),
        }
    }
}

fn build_integer_value(
    value: i32,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Value {
    if my_ir_generator_info.curr_func.is_none() {
        program.new_value().integer(value)
    } else {
        create_new_local_value(program, my_ir_generator_info).integer(value)
    }
}

fn build_value_from_result(
    result: IRExpBuildResult,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<Value, String> {
    match result {
        IRExpBuildResult::Const(int) => Ok(build_integer_value(int, program, my_ir_generator_info)),
        IRExpBuildResult::Value(value) => Ok(value),
    }
}

fn eval_binary_const(lhs: i32, rhs: i32, binary_op: koopa::ir::BinaryOp) -> i32 {
    use koopa::ir::BinaryOp;
    match binary_op {
        BinaryOp::NotEq => (lhs != rhs) as i32,
        BinaryOp::Eq => (lhs == rhs) as i32,
        BinaryOp::Gt => (lhs > rhs) as i32,
        BinaryOp::Lt => (lhs < rhs) as i32,
        BinaryOp::Ge => (lhs >= rhs) as i32,
        BinaryOp::Le => (lhs <= rhs) as i32,
        BinaryOp::Add => lhs + rhs,
        BinaryOp::Sub => lhs - rhs,
        BinaryOp::Mul => lhs * rhs,
        BinaryOp::Div => lhs / rhs,
        BinaryOp::Mod => lhs % rhs,
        BinaryOp::And => lhs & rhs,
        BinaryOp::Or => lhs | rhs,
        BinaryOp::Xor => lhs ^ rhs,
        BinaryOp::Shl => lhs << rhs,
        BinaryOp::Shr => ((lhs as u32) >> rhs) as i32,
        BinaryOp::Sar => lhs >> rhs,
    }
}

fn build_bool_result(
    result: IRExpBuildResult,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> Result<IRExpBuildResult, String> {
    match result {
        IRExpBuildResult::Const(int) => Ok(IRExpBuildResult::Const((int != 0) as i32)),
        IRExpBuildResult::Value(value) => {
            let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
            let bool_value = create_new_local_value(program, my_ir_generator_info)
                .binary(koopa::ir::BinaryOp::NotEq, value, zero);
            insert_local_instructions(program, my_ir_generator_info, [bool_value]);
            Ok(IRExpBuildResult::Value(bool_value))
        }
    }
}

fn build_binary_from_build_results(
    result1: IRExpBuildResult,
    result2: IRExpBuildResult,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
    binary_op: koopa::ir::BinaryOp,
) -> Result<IRExpBuildResult, String> {
    match (result1, result2) {
        (IRExpBuildResult::Const(lhs), IRExpBuildResult::Const(rhs)) => {
            Ok(IRExpBuildResult::Const(eval_binary_const(lhs, rhs, binary_op)))
        }
        (lhs, rhs) => {
            if my_ir_generator_info.curr_func.is_none() {
                return Err("Non-constant global expression is not allowed. ".to_string());
            }
            let lhs = build_value_from_result(lhs, program, my_ir_generator_info)?;
            let rhs = build_value_from_result(rhs, program, my_ir_generator_info)?;
            let value =
                create_new_local_value(program, my_ir_generator_info).binary(binary_op, lhs, rhs);
            insert_local_instructions(program, my_ir_generator_info, [value]);
            Ok(IRExpBuildResult::Value(value))
        }
    }
}

impl IRExpBuildable for LOrExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            LOrExp::LAndExp(exp) => exp.build(program, my_ir_generator_info),
            LOrExp::BinaryLOrExp(lhs, rhs) => {
                let lhs_result = lhs.build(program, my_ir_generator_info)?;
                match lhs_result {
                    IRExpBuildResult::Const(int) => {
                        if int != 0 {
                            Ok(IRExpBuildResult::Const(1))
                        } else {
                            build_bool_result(rhs.build(program, my_ir_generator_info)?, program, my_ir_generator_info)
                        }
                    }
                    IRExpBuildResult::Value(_) => {
                        let lhs_bool =
                            build_bool_result(lhs_result, program, my_ir_generator_info)?;
                        let lhs_value = build_value_from_result(
                            lhs_bool,
                            program,
                            my_ir_generator_info,
                        )?;
                        let result_ptr =
                            create_new_local_value(program, my_ir_generator_info).alloc(Type::get_i32());
                        let one = create_new_local_value(program, my_ir_generator_info).integer(1);
                        let store_default = create_new_local_value(program, my_ir_generator_info)
                            .store(one, result_ptr);
                        let rhs_block =
                            create_new_block(program, my_ir_generator_info, "lor_rhs");
                        let end_block =
                            create_new_block(program, my_ir_generator_info, "lor_end");
                        insert_basic_blocks(
                            program,
                            my_ir_generator_info,
                            [rhs_block, end_block],
                        );
                        let br = create_new_local_value(program, my_ir_generator_info)
                            .branch(lhs_value, end_block, rhs_block);
                        insert_local_instructions(
                            program,
                            my_ir_generator_info,
                            [result_ptr, store_default, br],
                        );

                        my_ir_generator_info.curr_block = Some(rhs_block);
                        let rhs_bool = build_bool_result(
                            rhs.build(program, my_ir_generator_info)?,
                            program,
                            my_ir_generator_info,
                        )?;
                        let rhs_value = build_value_from_result(
                            rhs_bool,
                            program,
                            my_ir_generator_info,
                        )?;
                        let store_rhs = create_new_local_value(program, my_ir_generator_info)
                            .store(rhs_value, result_ptr);
                        let jump_end =
                            create_new_local_value(program, my_ir_generator_info).jump(end_block);
                        insert_local_instructions(
                            program,
                            my_ir_generator_info,
                            [store_rhs, jump_end],
                        );

                        my_ir_generator_info.curr_block = Some(end_block);
                        let load_result =
                            create_new_local_value(program, my_ir_generator_info).load(result_ptr);
                        insert_local_instructions(program, my_ir_generator_info, [load_result]);
                        Ok(IRExpBuildResult::Value(load_result))
                    }
                }
            }
        }
    }
}

