impl IRExpBuildable for UnaryExp {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRExpBuildResult, String> {
        match self {
            UnaryExp::PrimaryExp(exp) => exp.build(program, my_ir_generator_info),
            UnaryExp::PlusUnaryExp(exp) => exp.build(program, my_ir_generator_info),
            UnaryExp::MinusUnaryExp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok(IRExpBuildResult::Const(-int)),
                IRExpBuildResult::Value(value) => {
                    let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                    let minus = create_new_local_value(program, my_ir_generator_info)
                        .binary(koopa::ir::BinaryOp::Sub, zero, value);
                    insert_local_instructions(program, my_ir_generator_info, [minus]);
                    Ok(IRExpBuildResult::Value(minus))
                }
            },
            UnaryExp::NotUnaryExp(exp) => match exp.build(program, my_ir_generator_info)? {
                IRExpBuildResult::Const(int) => Ok(IRExpBuildResult::Const((int == 0) as i32)),
                IRExpBuildResult::Value(value) => {
                    let zero = create_new_local_value(program, my_ir_generator_info).integer(0);
                    let not = create_new_local_value(program, my_ir_generator_info)
                        .binary(koopa::ir::BinaryOp::Eq, value, zero);
                    insert_local_instructions(program, my_ir_generator_info, [not]);
                    Ok(IRExpBuildResult::Value(not))
                }
            },
            UnaryExp::FuncCall(ident, args) => {
                let function = *my_ir_generator_info
                    .function_table
                    .get(&ident.content)
                    .ok_or_else(|| format!("Undeclared function: {}", ident.content))?;
                let (param_types, _ret_type) = match program.func(function).ty().kind() {
                    TypeKind::Function(params, ret) => (params.clone(), ret.clone()),
                    _ => return Err(format!("{} is not a function. ", ident.content)),
                };
                if param_types.len() != args.len() {
                    return Err(format!(
                        "Function '{}' expects {} arguments but got {}. ",
                        ident.content,
                        param_types.len(),
                        args.len()
                    ));
                }

                let mut arg_values = Vec::with_capacity(args.len());
                for (arg, param_type) in args.iter().zip(param_types.iter()) {
                    let arg_value =
                        build_value_from_result(arg.build(program, my_ir_generator_info)?, program, my_ir_generator_info)?;
                    if get_valuedata(arg_value, program, my_ir_generator_info).ty() != param_type {
                        return Err(format!(
                            "Type mismatch in call to '{}': expected {}, got {}. ",
                            ident.content,
                            param_type,
                            get_valuedata(arg_value, program, my_ir_generator_info).ty()
                        ));
                    }
                    arg_values.push(arg_value);
                }
                let call = create_new_local_value(program, my_ir_generator_info)
                    .call(function, arg_values);
                insert_local_instructions(program, my_ir_generator_info, [call]);
                Ok(IRExpBuildResult::Value(call))
            }
        }
    }
}

impl IRExpBuildable for PrimaryExp {
