impl IRBuildable for BasicStmt {
    fn build(
        &self,
        program: &mut Program,
        my_ir_generator_info: &mut MyIRGeneratorInfo,
    ) -> Result<IRBuildResult, String> {
        match self {
            BasicStmt::AssignStmt(lval, exp) => {
                let addr = match lval.build(program, my_ir_generator_info)? {
                    IRLValBuildResult::Addr(addr) => addr,
                    _ => return Err("Assignment target must be an addressable lvalue. ".to_string()),
                };
                let value = build_value_from_result(
                    exp.build(program, my_ir_generator_info)?,
                    program,
                    my_ir_generator_info,
                );
                let store = create_new_local_value(program, my_ir_generator_info).store(value, addr);
                insert_local_instructions(program, my_ir_generator_info, [store]);
                Ok(IRBuildResult::OK)
            }
            BasicStmt::Exp(exp) => {
                if let Some(exp) = exp {
                    exp.build(program, my_ir_generator_info)?;
                }
                Ok(IRBuildResult::OK)
            }
            BasicStmt::Block(block) => {
                my_ir_generator_info.symbol_tables.add_new_table();
                block.build(program, my_ir_generator_info)
            }
            BasicStmt::IfStmt(cond, then_stmt, else_stmt) => {
                let cond_result = cond.build(program, my_ir_generator_info)?;
                match cond_result {
                    IRExpBuildResult::Const(int) => {
                        if int != 0 {
                            then_stmt.build(program, my_ir_generator_info)
                        } else if let Some(else_stmt) = else_stmt.as_ref().as_ref() {
                            else_stmt.build(program, my_ir_generator_info)
                        } else {
                            Ok(IRBuildResult::OK)
                        }
                    }
                    IRExpBuildResult::Value(cond_value) => {
                        if else_stmt.as_ref().is_none() {
                            let then_block =
                                create_new_block(program, my_ir_generator_info, "if_then");
                            let end_block =
                                create_new_block(program, my_ir_generator_info, "if_end");
                            insert_basic_blocks(
                                program,
                                my_ir_generator_info,
                                [then_block, end_block],
                            );
                            let br = create_new_local_value(program, my_ir_generator_info)
                                .branch(cond_value, then_block, end_block);
                            insert_local_instructions(program, my_ir_generator_info, [br]);

                            my_ir_generator_info.curr_block = Some(then_block);
                            let then_result = then_stmt.build(program, my_ir_generator_info)?;
                            if matches!(then_result, IRBuildResult::OK) {
                                let jump_end =
                                    create_new_local_value(program, my_ir_generator_info).jump(end_block);
                                insert_local_instructions(
                                    program,
                                    my_ir_generator_info,
                                    [jump_end],
                                );
                            }
                            my_ir_generator_info.curr_block = Some(end_block);
                            Ok(IRBuildResult::OK)
                        } else {
                            let then_block =
                                create_new_block(program, my_ir_generator_info, "if_then");
                            let else_block =
                                create_new_block(program, my_ir_generator_info, "if_else");
                            let end_block =
                                create_new_block(program, my_ir_generator_info, "if_end");
                            insert_basic_blocks(
                                program,
                                my_ir_generator_info,
                                [then_block, else_block],
                            );
                            let br = create_new_local_value(program, my_ir_generator_info)
                                .branch(cond_value, then_block, else_block);
                            insert_local_instructions(program, my_ir_generator_info, [br]);

                            my_ir_generator_info.curr_block = Some(then_block);
                            let then_result = then_stmt.build(program, my_ir_generator_info)?;
                            if matches!(then_result, IRBuildResult::OK) {
                                let jump_end =
                                    create_new_local_value(program, my_ir_generator_info).jump(end_block);
                                insert_local_instructions(
                                    program,
                                    my_ir_generator_info,
                                    [jump_end],
                                );
                            }

                            my_ir_generator_info.curr_block = Some(else_block);
                            let else_result = else_stmt
                                .as_ref()
                                .as_ref()
                                .unwrap()
                                .build(program, my_ir_generator_info)?;
                            if matches!(else_result, IRBuildResult::OK) {
                                let jump_end =
                                    create_new_local_value(program, my_ir_generator_info).jump(end_block);
                                insert_local_instructions(
                                    program,
                                    my_ir_generator_info,
                                    [jump_end],
                                );
                            }

                            if matches!(then_result, IRBuildResult::OK)
                                || matches!(else_result, IRBuildResult::OK)
                            {
                                insert_basic_blocks(program, my_ir_generator_info, [end_block]);
                                my_ir_generator_info.curr_block = Some(end_block);
                                Ok(IRBuildResult::OK)
                            } else {
                                Ok(IRBuildResult::EARLYSTOPPING)
                            }
                        }
                    }
                }
            }
            BasicStmt::WhileStmt(cond, body) => {
                let cond_block =
                    create_new_block(program, my_ir_generator_info, "while_start");
                let body_block =
                    create_new_block(program, my_ir_generator_info, "while_body");
                let end_block =
                    create_new_block(program, my_ir_generator_info, "while_end");
                insert_basic_blocks(
                    program,
                    my_ir_generator_info,
                    [cond_block, body_block, end_block],
                );

                let jump_cond =
                    create_new_local_value(program, my_ir_generator_info).jump(cond_block);
                insert_local_instructions(program, my_ir_generator_info, [jump_cond]);

                my_ir_generator_info.curr_block = Some(cond_block);
                match cond.build(program, my_ir_generator_info)? {
                    IRExpBuildResult::Const(int) => {
                        let jump_target = if int != 0 { body_block } else { end_block };
                        let jump = create_new_local_value(program, my_ir_generator_info)
                            .jump(jump_target);
                        insert_local_instructions(program, my_ir_generator_info, [jump]);
                    }
                    IRExpBuildResult::Value(cond_value) => {
                        let br = create_new_local_value(program, my_ir_generator_info)
                            .branch(cond_value, body_block, end_block);
                        insert_local_instructions(program, my_ir_generator_info, [br]);
                    }
                }

                my_ir_generator_info.break_tgt_blocks.push(end_block);
                my_ir_generator_info.continue_tgt_blocks.push(cond_block);
                my_ir_generator_info.curr_block = Some(body_block);
                let body_result = body.build(program, my_ir_generator_info)?;
                if matches!(body_result, IRBuildResult::OK) {
                    let jump_cond =
                        create_new_local_value(program, my_ir_generator_info).jump(cond_block);
                    insert_local_instructions(program, my_ir_generator_info, [jump_cond]);
                }
                my_ir_generator_info.break_tgt_blocks.pop();
                my_ir_generator_info.continue_tgt_blocks.pop();
                my_ir_generator_info.curr_block = Some(end_block);
                Ok(IRBuildResult::OK)
            }
            BasicStmt::BreakStmt => {
                let target = *my_ir_generator_info
                    .break_tgt_blocks
                    .last()
                    .ok_or_else(|| "break statement is not inside a loop. ".to_string())?;
                let jump = create_new_local_value(program, my_ir_generator_info).jump(target);
                insert_local_instructions(program, my_ir_generator_info, [jump]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
            BasicStmt::ContinueStmt => {
                let target = *my_ir_generator_info
                    .continue_tgt_blocks
                    .last()
                    .ok_or_else(|| "continue statement is not inside a loop. ".to_string())?;
                let jump = create_new_local_value(program, my_ir_generator_info).jump(target);
                insert_local_instructions(program, my_ir_generator_info, [jump]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
            BasicStmt::ReturnStmt(exp) => {
                let ret_value = exp
                    .as_ref()
                    .map(|exp| {
                        build_value_from_result(
                            exp.build(program, my_ir_generator_info)?,
                            program,
                            my_ir_generator_info,
                        )
                    })
                    .transpose()?;

                    .transpose()?;
                let ret = create_new_local_value(program, my_ir_generator_info).ret(ret_value);
                insert_local_instructions(program, my_ir_generator_info, [ret]);
                Ok(IRBuildResult::EARLYSTOPPING)
            }
        }
    }
}

//! This module is the backend of my compiler.
//! It converts the Koopa IR into assembly code.

mod build_assembly;
use std::collections::HashMap;
use std::io::Write;

use build_assembly::AssemblyBuildable;
use koopa::ir::{FunctionData, Program, Value, ValueKind};

pub fn generate_assembly(program: &Program, output_file: &mut std::fs::File) -> Result<(), String> {
    let codes = program.build(program)?;
    for code in codes {
        writeln!(output_file, "{}", code).expect("Write error. ");
    }
    Ok(())
}

const REGISTER_NAMES: [&str; 32] = [
    "zero", "ra", "sp", "gp", "tp", "t0", "t1", "t2", "fp", "s1", "a0", "a1", "a2", "a3", "a4",
    "a5", "a6", "a7", "s2", "s3", "s4", "s5", "s6", "s7", "s8", "s9", "s10", "s11", "t3", "t4",
    "t5", "x31",
];

// const REGISTER_FOR_TEMP: [usize; 7] = [5, 6, 7, 28, 29, 30, 31];
const REGISTER_FOR_TEMP: [usize; 6] = [5, 6, 7, 28, 29, 30];
// const REGISTER_FOR_TEMP: [usize; 2] = [5, 6];

const REGISTER_FOR_ARGS: [usize; 8] = [10, 11, 12, 13, 14, 15, 16, 17];

const ARG_SIZE: usize = 4;

const REG_A0: usize = 10;
const REG_SP: usize = 2;
const REG_RA: usize = 1;
/// This register is for temporary integers only!
const REG_X31: usize = 31;

const MAX_SHORT_INT: isize = 2047;
const MIN_SHORT_INT: isize = -2048;

pub struct MyBBValueTable<'a> {
    program: &'a Program,
    fd: &'a FunctionData,
    stack_frame_size: usize,
    curr_time: i32,
    register_user: [Option<Value>; 32],
    register_used_time: [i32; 32], // LRU registers
    local_value_location: HashMap<Value, usize>,
}

impl MyBBValueTable<'_> {
    fn new<'a>(program: &'a Program, fd: &'a FunctionData) -> MyBBValueTable<'a> {
        MyBBValueTable {
            program,
            fd,
            stack_frame_size: 0,
            curr_time: 0,
            register_user: [None; 32],
            register_used_time: [0; 32],
            local_value_location: HashMap::new(),
        }
    }

    fn __update_user(&mut self, reg: usize, user: Value) {
        self.curr_time += 1;
        self.register_user[reg] = Some(user);
        self.register_used_time[reg] = self.curr_time;
    }
    fn __free_user(&mut self, reg: usize) {
        self.register_user[reg] = None;
        self.register_used_time[reg] = 0;
    }

    fn __is_value_in_register(&self, value: Value) -> Option<usize> {
        for i in 0..REGISTER_NAMES.len() {
            match self.register_user[i] {
                Some(v) => {
                    if v == value {
                        return Some(i);
                    }
                }
                None => {}
            }
        }
        None
    }

    fn __value_data(&self, value: Value) -> koopa::ir::entities::ValueData {
        if value.is_global() {
            self.program.borrow_value(value).clone()
        } else {
            self.fd.dfg().value(value).clone()
        }
    }

    fn is_temp_value(&self, value: Value) -> bool {
        let value_data = self.__value_data(value);
        match value_data.name() {
            Some(name) => name.starts_with("%"),
            None => true,
        }
    }

    fn remove_temp_value(&mut self, value: Value) {
        // assert!(
        //     self.is_temp_value(value),
        //     "Can only remove temp values in table!"
        // );
        if !self.is_temp_value(value) {
            return;
        }
        if let Some(reg) = self.__is_value_in_register(value) {
            self.__free_user(reg);
        }
        self.local_value_location.remove(&value);
    }

    fn store_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
        if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
            vec![format!(
                "  sw\t{}, {}({})",
                REGISTER_NAMES[reg], offset, REGISTER_NAMES[REG_SP]
            )]
        } else {
            vec![
                format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset),
                format!(
                    "  add\t{}, {}, {}",
                    REGISTER_NAMES[REG_X31], REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_X31]
                ),
                format!(
                    "  sw\t{}, 0({})",
                    REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]
                ),
            ]
        }
    }
    fn load_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
        if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
            vec![format!(
                "  lw\t{}, {}({})",
                REGISTER_NAMES[reg], offset, REGISTER_NAMES[REG_SP]
            )]
        } else {
            vec![
                format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset),
                format!(
                    "  add\t{}, {}, {}",
                    REGISTER_NAMES[REG_X31], REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_X31]
                ),
                format!(
                    "  lw\t{}, 0({})",
                    REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]
                ),
            ]
        }
    }
    fn add_with_offset(&mut self, reg: usize, offset: isize) -> Vec<String> {
        if (MIN_SHORT_INT..=MAX_SHORT_INT).contains(&offset) {
            vec![format!(
                "  addi\t{}, {}, {}",
                REGISTER_NAMES[reg], REGISTER_NAMES[REG_SP], offset
            )]
        } else {
            vec![
                format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], offset),
                format!(
                    "  add\t{}, {}, {}",
                    REGISTER_NAMES[reg], REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_X31]
                ),
            ]
        }
    }
    fn load_global(&mut self, reg: usize, symbol_name: String) -> Vec<String> {
        vec![format!(
            "  la\t{}, {}\n  lw\t{}, 0({})",
            REGISTER_NAMES[REG_X31], symbol_name, REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]
        )]
    }
    fn store_global(&mut self, reg: usize, symbol_name: String) -> Vec<String> {
        vec![format!(
            "  la\t{}, {}\n  sw\t{}, 0({})",
            REGISTER_NAMES[REG_X31], symbol_name, REGISTER_NAMES[reg], REGISTER_NAMES[REG_X31]
        )]
    }

    fn store_global_variables(&mut self) -> Vec<String> {
        let mut codes = vec![];
        for reg in 0..REGISTER_NAMES.len() {
            let Some(value) = self.register_user[reg] else {
                continue;
            };
            if value.is_global() && !self.is_temp_value(value) {
                codes.extend(self.save_register(reg));
            }
        }
        codes
    }

    fn store_local_variables(&mut self) -> Vec<String> {
        let mut codes = vec![];
        for reg in 0..REGISTER_NAMES.len() {
            let Some(value) = self.register_user[reg] else {
                continue;
            };
            if !value.is_global() && !self.is_temp_value(value) {
                codes.extend(self.save_register(reg));
            }
        }
        codes
    }

    /// Kick the value in a register and store it to memory.
    fn save_register(&mut self, reg: usize) -> Vec<String> {
        let Some(value) = self.register_user[reg] else {
            return vec![];
        };
        let value_data = self.__value_data(value);
        let mut codes = vec![];
        match value_data.kind() {
            ValueKind::Integer(_) => {}
            ValueKind::FuncArgRef(_) => {}
            ValueKind::GlobalAlloc(_) => {
                if let Some(name) = value_data.name() {
                    codes.extend(self.store_global(reg, name.trim_start_matches('@').to_string()));
                }
            }
            ValueKind::Alloc(_) => {
                if let Some(offset) = self.local_value_location.get(&value).copied() {
                    codes.extend(self.store_with_offset(reg, offset as isize));
                }
            }
            _ => {
                if let Some(offset) = self.local_value_location.get(&value).copied() {
                    codes.extend(self.store_with_offset(reg, offset as isize));
                }
            }
        }
        self.__free_user(reg);
        codes
    }

    /// Finds a usable register.
    /// If all registers are being used, then kicks one.
    fn get_tmp_reg(&mut self) -> (usize, Vec<String>) {
        for reg in REGISTER_FOR_TEMP {
            if self.register_user[reg].is_none() {
                return (reg, vec![]);
            }
        }
        let reg = *REGISTER_FOR_TEMP
            .iter()
            .min_by_key(|&&reg| self.register_used_time[reg])
            .unwrap();
        let codes = self.save_register(reg);
        (reg, codes)
    }

    /// Want to visit a value. Make it appear in a register.
    fn want_to_visit_value(
        &mut self,
        value: Value,
        do_load: bool,
        use_certain_reg: Option<usize>,
    ) -> (usize, Vec<String>) {
        if let Some(reg) = self.__is_value_in_register(value) {
            if let Some(target_reg) = use_certain_reg {
                if reg == target_reg {
                    self.__update_user(reg, value);
                    return (reg, vec![]);
                }
                let mut codes = vec![];
                if let Some(other) = self.register_user[target_reg] {
                    if other != value {
                        codes.extend(self.save_register(target_reg));
                    }
                }
                codes.push(format!(
                    "  mv\t{}, {}",

                    "  mv\t{}, {}",
                    REGISTER_NAMES[target_reg], REGISTER_NAMES[reg]
                ));
                self.__free_user(reg);
                self.__update_user(target_reg, value);
                return (target_reg, codes);
            }
            self.__update_user(reg, value);
            return (reg, vec![]);
        }

        let (reg, mut codes) = if let Some(target_reg) = use_certain_reg {
            let mut target_codes = vec![];
            if self.register_user[target_reg].is_some() {
                target_codes.extend(self.save_register(target_reg));
            }
            (target_reg, target_codes)
        } else {
            self.get_tmp_reg()
        };

        let value_data = self.__value_data(value);
        match value_data.kind() {
            ValueKind::Integer(integer) => {
                codes.push(format!("  li\t{}, {}", REGISTER_NAMES[reg], integer.value()));
            }
            ValueKind::FuncArgRef(arg) => {
                if arg.index() < REGISTER_FOR_ARGS.len() {
                    codes.push(format!(
                        "  mv\t{}, {}",
                        REGISTER_NAMES[reg], REGISTER_NAMES[REGISTER_FOR_ARGS[arg.index()]]
                    ));
                } else {
                    let offset =
                        self.stack_frame_size as isize + ((arg.index() - REGISTER_FOR_ARGS.len()) * ARG_SIZE) as isize;
                    codes.extend(self.load_with_offset(reg, offset));
                }
            }
            ValueKind::GlobalAlloc(_) => {
                if do_load {
                    if let Some(name) = value_data.name() {
                        codes.extend(self.load_global(reg, name.trim_start_matches('@').to_string()));
                    }
                } else if let Some(name) = value_data.name() {
                    codes.push(format!(
                        "  la\t{}, {}",
                        REGISTER_NAMES[reg],
                        name.trim_start_matches('@')
                    ));
                }
            }
            ValueKind::Alloc(_) => {
                if let Some(offset) = self.local_value_location.get(&value).copied() {
                    if do_load {
                        codes.extend(self.load_with_offset(reg, offset as isize));
                    } else {
                        codes.extend(self.add_with_offset(reg, offset as isize));
                    }
                }
            }
            _ => {
                if let Some(offset) = self.local_value_location.get(&value).copied() {
                    codes.extend(self.load_with_offset(reg, offset as isize));
                }
            }
        }
        self.__update_user(reg, value);
        (reg, codes)
    }

    fn assign_v1_to_v2(&mut self, v1: Value, v2: Value) -> Vec<String> {
        let (src_reg, mut codes) = self.want_to_visit_value(v1, true, None);
        let target_reg = if let Some(reg) = self.__is_value_in_register(v2) {
            if reg == src_reg {
                let mut candidate = None;
                for tmp_reg in REGISTER_FOR_TEMP {
                    if tmp_reg != src_reg && self.register_user[tmp_reg].is_none() {
                        candidate = Some((tmp_reg, vec![]));
                        break;
                    }
                }
                if let Some((reg, extra)) = candidate {
                    codes.extend(extra);
                    reg
                } else {
                    let reg = *REGISTER_FOR_TEMP
                        .iter()
                        .filter(|&&reg| reg != src_reg)
                        .min_by_key(|&&reg| self.register_used_time[reg])
                        .unwrap();
                    codes.extend(self.save_register(reg));
                    reg
                }
            } else {
                reg
            }
        } else if let Some(reg) = REGISTER_FOR_TEMP
            .iter()
            .copied()
            .find(|&reg| reg != src_reg && self.register_user[reg].is_none())
        {
            reg
        } else {
            let reg = *REGISTER_FOR_TEMP
                .iter()
                .filter(|&&reg| reg != src_reg)
                .min_by_key(|&&reg| self.register_used_time[reg])
                .unwrap();
            codes.extend(self.save_register(reg));
            reg
        };

        if let Some(other) = self.register_user[target_reg] {
            if other != v2 {
                codes.extend(self.save_register(target_reg));
            }
        }
        codes.push(format!(
            "  mv\t{}, {}",
            REGISTER_NAMES[target_reg], REGISTER_NAMES[src_reg]
        ));
        self.__update_user(target_reg, v2);
        codes
    }

    /// Example:
    /// getelemptr @a, 114 -> The absolute location of @a in memory.
    /// getelemptr %0, 514 -> The value of %0 (which is an address).
    fn get_absolute_location(&mut self, value: Value) -> (usize, Vec<String>) {
        match self.__value_data(value).kind() {
            ValueKind::GlobalAlloc(_) => {
                let (reg, mut codes) = self.get_tmp_reg();
                if let Some(name) = self.__value_data(value).name() {
                    codes.push(format!(
                        "  la\t{}, {}",
                        REGISTER_NAMES[reg],
                        name.trim_start_matches('@')
                    ));
                }
                (reg, codes)
            }
            ValueKind::Alloc(_) => {
                let (reg, mut codes) = self.get_tmp_reg();
                if let Some(offset) = self.local_value_location.get(&value).copied() {
                    codes.extend(self.add_with_offset(reg, offset as isize));
                }
                (reg, codes)
            }
            _ => self.want_to_visit_value(value, false, None),
        }
    }

    fn clear_registers(&mut self) {
        self.register_user = [None; 32];
        self.register_used_time = [0; 32];
    }
}

