//! Convert a single Koopa IR component into assembly code.

use crate::assembly_builder::{REG_RA, REG_X31};

use super::{
    MyBBValueTable, ARG_SIZE, REGISTER_FOR_ARGS, REGISTER_NAMES, REG_A0, REG_SP,
};
use koopa::ir::{entities::{BasicBlock, ValueData}, FunctionData, Program, Type, TypeKind, ValueKind};

pub trait AssemblyBuildable {
    fn build(&self, program: &Program) -> Result<Vec<String>, String>;
}

fn align_to(value: usize, align: usize) -> usize {
    if value == 0 {
        0
    } else {
        ((value + align - 1) / align) * align
    }
}

fn adjust_sp(delta: isize) -> Vec<String> {
    if delta == 0 {
        vec![]
    } else if (-2048..=2047).contains(&delta) {
        vec![format!(
            "  addi\t{}, {}, {}",
            REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_SP], delta
        )]
    } else if delta < 0 {
        vec![
            format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], -delta),
            format!(
                "  sub\t{}, {}, {}",
                REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_X31]
            ),
        ]
    } else {
        vec![
            format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], delta),
            format!(
                "  add\t{}, {}, {}",
                REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_SP], REGISTER_NAMES[REG_X31]
            ),
        ]
    }
}

fn func_label(name: &str) -> String {
    name.trim_start_matches('@').to_string()
}

fn bb_label(fd: &FunctionData, bb: BasicBlock) -> String {
    if let Some(name) = fd.dfg().bb(bb).name() {
        format!(".{}", name.trim_start_matches('%').trim_start_matches('@'))
    } else {
        let debug_name = format!("{:?}", bb);
        let id = debug_name
            .trim_start_matches("BasicBlock(")
            .trim_end_matches(')');
        format!(".bb{}", id)
    }
}

fn local_slot_size(value_data: &ValueData) -> usize {
    match value_data.kind() {
        ValueKind::Alloc(_) => match value_data.ty().kind() {
            TypeKind::Pointer(base) => base.size(),
            _ => 0,
        },
        _ if !value_data.ty().is_unit() => value_data.ty().size(),
        _ => 0,
    }
}

fn append_zero_words(ty: &Type, codes: &mut Vec<String>) {
    match ty.kind() {
        TypeKind::Int32 | TypeKind::Pointer(_) => codes.push("  .word 0".to_string()),
        TypeKind::Array(base, len) => {
            for _ in 0..*len {
                append_zero_words(base, codes);
            }
        }
        TypeKind::Unit | TypeKind::Function(_, _) => {}
    }
}

fn append_global_value(value: koopa::ir::Value, program: &Program, codes: &mut Vec<String>) {
    let value_data = program.borrow_value(value);
    match value_data.kind() {
        ValueKind::Integer(integer) => codes.push(format!("  .word {}", integer.value())),
        ValueKind::ZeroInit(_) => append_zero_words(value_data.ty(), codes),
        ValueKind::Aggregate(aggregate) => {
            for elem in aggregate.elems() {
                append_global_value(*elem, program, codes);
            }
        }
        _ => {}
    }
}

impl AssemblyBuildable for Program {
    fn build(&self, _: &Program) -> Result<Vec<String>, String> {
        let mut codes = vec![];

        if !self.inst_layout().is_empty() {
            codes.push("  .data".to_string());
            for value in self.inst_layout() {
                codes.extend(self.borrow_value(*value).build(self)?);
            }
        }

        let mut has_definition = false;
        for func in self.func_layout() {
            if self.func(*func).layout().entry_bb().is_some() {
                has_definition = true;
                break;
            }
        }
        if has_definition {
            codes.push("  .text".to_string());
            for func in self.func_layout() {
                codes.extend(self.func(*func).build(self)?);
            }
        }

        Ok(codes)
    }
}

fn binary_op_to_assembly(
    binary: &koopa::ir::values::Binary,
    reg_ans: usize,
    reg1: usize,
    reg2: usize,
) -> String {
    use koopa::ir::BinaryOp;
    match binary.op() {
        BinaryOp::Add => format!(
            "  add\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Sub => format!(
            "  sub\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Mul => format!(
            "  mul\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Div => format!(
            "  div\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Mod => format!(
            "  rem\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::And => format!(
            "  and\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Or => format!(
            "  or\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Xor => format!(
            "  xor\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Shl => format!(
            "  sll\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Shr => format!(
            "  srl\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Sar => format!(
            "  sra\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Eq => format!(
            "  xor\t{}, {}, {}\n  seqz\t{}, {}",
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg1],
            REGISTER_NAMES[reg2],
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg_ans]
        ),
        BinaryOp::NotEq => format!(
            "  xor\t{}, {}, {}\n  snez\t{}, {}",
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg1],
            REGISTER_NAMES[reg2],
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg_ans]
        ),
        BinaryOp::Lt => format!(
            "  slt\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Gt => format!(
            "  sgt\t{}, {}, {}",
            REGISTER_NAMES[reg_ans], REGISTER_NAMES[reg1], REGISTER_NAMES[reg2]
        ),
        BinaryOp::Le => format!(
            "  sgt\t{}, {}, {}\n  xori\t{}, {}, 1",
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg1],
            REGISTER_NAMES[reg2],
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg_ans]
        ),
        BinaryOp::Ge => format!(
            "  slt\t{}, {}, {}\n  xori\t{}, {}, 1",
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg1],
            REGISTER_NAMES[reg2],
            REGISTER_NAMES[reg_ans],
            REGISTER_NAMES[reg_ans]
        ),
    }
}

fn init_global_aggregate(aggr: &koopa::ir::values::Aggregate, program: &Program) -> Vec<String> {
    let mut codes = vec![];
    for elem in aggr.elems() {
        append_global_value(*elem, program, &mut codes);
    }
    codes
}

impl AssemblyBuildable for ValueData {
    /// Used to handle global variable declarations.
    /// The ValueData's kind should be GlobalAlloc. Or it will panic.
    fn build(&self, program: &Program) -> Result<Vec<String>, String> {
        let ValueKind::GlobalAlloc(global_alloc) = self.kind() else {
            return Err("Expected a global allocation. ".to_string());
        };
        let name = self
            .name()
            .as_ref()
            .ok_or_else(|| "Global allocation is missing a symbol name. ".to_string())?;
        let mut codes = vec![format!("{}:", name.trim_start_matches('@'))];
        let init_data = program.borrow_value(global_alloc.init());
        match init_data.kind() {
            ValueKind::Integer(integer) => {
                codes.push(format!("  .word {}", integer.value()));
            }
            ValueKind::ZeroInit(_) => {
                codes.push(format!("  .zero {}", init_data.ty().size()));
            }
            ValueKind::Aggregate(aggregate) => {
                codes.extend(init_global_aggregate(aggregate, program));
            }
            _ => return Err("Unsupported global initializer kind. ".to_string()),
        }
        Ok(codes)
    }
}

impl AssemblyBuildable for FunctionData {
    fn build(&self, program: &Program) -> Result<Vec<String>, String> {
        if self.layout().entry_bb().is_none() {
            return Ok(vec![]);
        }

        let mut max_extra_arg_count = 0usize;
        let mut has_call = false;
        for (_bb, bb_node) in self.layout().bbs().iter() {
            for (value, _inst_node) in bb_node.insts().iter() {
                if let ValueKind::Call(call) = self.dfg().value(*value).kind() {
                    has_call = true;
                    max_extra_arg_count = max_extra_arg_count.max(call.args().len().saturating_sub(REGISTER_FOR_ARGS.len()));
                }
            }
        }

        let outgoing_arg_space = max_extra_arg_count * ARG_SIZE;
        let mut next_offset = outgoing_arg_space;
        let mut value_locations = std::collections::HashMap::new();
        for (_bb, bb_node) in self.layout().bbs().iter() {
            for (value, _inst_node) in bb_node.insts().iter() {
                let value_data = self.dfg().value(*value);
                let slot_size = local_slot_size(value_data);
                if slot_size > 0 {
                    value_locations.insert(*value, next_offset);
                    next_offset += slot_size;
                }
            }
        }

        let raw_frame_size = next_offset + if has_call { ARG_SIZE } else { 0 };
        let frame_size = align_to(raw_frame_size, 16);
        let ra_offset = if has_call { frame_size - ARG_SIZE } else { 0 };

        let mut table = MyBBValueTable::new(program, self);
        table.stack_frame_size = frame_size;
        table.local_value_location = value_locations;

        let function_name = func_label(self.name());
        let return_label = format!(".{}_ret", function_name);
        let mut codes = vec![
            format!("  .global {}", function_name),
            format!("{}:", function_name),
        ];

        if frame_size > 0 {
            codes.extend(adjust_sp(-(frame_size as isize)));
        }
        if has_call {
            codes.extend(table.store_with_offset(REG_RA, ra_offset as isize));
        }

        for (bb, bb_node) in self.layout().bbs().iter() {
            let bb_data = self.dfg().bb(*bb);
            if bb_data.name().is_some() || Some(*bb) != self.layout().entry_bb() {
                codes.push(format!("{}:", bb_label(self, *bb)));
            }

            for (value, _inst_node) in bb_node.insts().iter() {
                let value = *value;
                let value_data = self.dfg().value(value);
                match value_data.kind() {
                    ValueKind::Return(ret) => {
                        if let Some(ret_value) = ret.value() {
                            let (reg, reg_codes) =
                                table.want_to_visit_value(ret_value, true, Some(REG_A0));
                            codes.extend(reg_codes);
                            debug_assert_eq!(reg, REG_A0);
                        }
                        codes.extend(table.store_global_variables());
                        codes.extend(table.store_local_variables());
                        table.clear_registers();
                        codes.push(format!("  j\t{}", return_label));
                    }
                    ValueKind::Binary(binary) => {
                        let (lhs_reg, lhs_codes) = table.want_to_visit_value(binary.lhs(), true, None);
                        let (rhs_reg, rhs_codes) = table.want_to_visit_value(binary.rhs(), true, None);
                        codes.extend(lhs_codes);
                        codes.extend(rhs_codes);
                        codes.push(binary_op_to_assembly(binary, lhs_reg, lhs_reg, rhs_reg));
                        table.__update_user(lhs_reg, value);
                        codes.extend(table.save_register(lhs_reg));
                        table.clear_registers();
                    }
                    ValueKind::Alloc(_) => {}
                    ValueKind::Store(store) => {
                        let (addr_reg, addr_codes) = table.get_absolute_location(store.dest());
                        let (value_reg, value_codes) =
                            table.want_to_visit_value(store.value(), true, None);
                        codes.extend(addr_codes);
                        codes.extend(value_codes);
                        codes.push(format!(
                            "  sw\t{}, 0({})",
                            REGISTER_NAMES[value_reg], REGISTER_NAMES[addr_reg]
                        ));
                        table.clear_registers();
                    }

                    }
                    ValueKind::Load(load) => {
                        let (addr_reg, addr_codes) = table.get_absolute_location(load.src());
                        codes.extend(addr_codes);
                        codes.push(format!(
                            "  lw\t{}, 0({})",
                            REGISTER_NAMES[addr_reg], REGISTER_NAMES[addr_reg]
                        ));
                        table.__update_user(addr_reg, value);
                        codes.extend(table.save_register(addr_reg));
                        table.clear_registers();
                    }
                    ValueKind::Jump(jump) => {
                        codes.extend(table.store_global_variables());
                        codes.extend(table.store_local_variables());
                        table.clear_registers();
                        codes.push(format!("  j\t{}", bb_label(self, jump.target())));
                    }
                    ValueKind::Branch(branch) => {
                        let (cond_reg, cond_codes) =
                            table.want_to_visit_value(branch.cond(), true, None);
                        codes.extend(cond_codes);
                        codes.extend(table.store_global_variables());
                        codes.extend(table.store_local_variables());
                        table.clear_registers();
                        codes.push(format!(
                            "  bnez\t{}, {}",
                            REGISTER_NAMES[cond_reg],
                            bb_label(self, branch.true_bb())
                        ));
                        codes.push(format!("  j\t{}", bb_label(self, branch.false_bb())));
                    }
                    ValueKind::Call(call) => {
                        table.clear_registers();
                        for (index, arg) in call.args().iter().enumerate() {
                            if index < REGISTER_FOR_ARGS.len() {
                                let (_reg, arg_codes) = table.want_to_visit_value(
                                    *arg,
                                    true,
                                    Some(REGISTER_FOR_ARGS[index]),
                                );
                                codes.extend(arg_codes);
                            } else {
                                let (reg, arg_codes) =
                                    table.want_to_visit_value(*arg, true, None);
                                codes.extend(arg_codes);
                                codes.extend(table.store_with_offset(
                                    reg,
                                    ((index - REGISTER_FOR_ARGS.len()) * ARG_SIZE) as isize,
                                ));
                            }
                        }
                        codes.push(format!(
                            "  call\t{}",
                            func_label(program.func(call.callee()).name())
                        ));
                        table.clear_registers();
                        if !value_data.ty().is_unit() {
                            let (reg, reg_codes) = table.get_tmp_reg();
                            codes.extend(reg_codes);
                            codes.push(format!(
                                "  mv\t{}, {}",
                                REGISTER_NAMES[reg], REGISTER_NAMES[REG_A0]
                            ));
                            table.__update_user(reg, value);
                            codes.extend(table.save_register(reg));
                            table.clear_registers();
                        }
                    }
                    ValueKind::GetPtr(get_ptr) => {
                        let (base_reg, base_codes) = table.get_absolute_location(get_ptr.src());
                        let (index_reg, index_codes) =
                            table.want_to_visit_value(get_ptr.index(), true, None);
                        codes.extend(base_codes);
                        codes.extend(index_codes);
                        let elem_size = match self.dfg().value(get_ptr.src()).ty().kind() {
                            TypeKind::Pointer(base) => base.size(),
                            _ => return Err("getptr source must be a pointer. ".to_string()),
                        };
                        if elem_size != 1 {
                            codes.push(format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], elem_size));
                            codes.push(format!(
                                "  mul\t{}, {}, {}",
                                REGISTER_NAMES[REG_X31],
                                REGISTER_NAMES[index_reg],
                                REGISTER_NAMES[REG_X31]
                            ));
                            codes.push(format!(
                                "  add\t{}, {}, {}",
                                REGISTER_NAMES[base_reg],
                                REGISTER_NAMES[base_reg],
                                REGISTER_NAMES[REG_X31]
                            ));
                        } else {
                            codes.push(format!(
                                "  add\t{}, {}, {}",
                                REGISTER_NAMES[base_reg],
                                REGISTER_NAMES[base_reg],
                                REGISTER_NAMES[index_reg]
                            ));
                        }
                        table.__update_user(base_reg, value);
                        codes.extend(table.save_register(base_reg));
                        table.clear_registers();
                    }
                    ValueKind::GetElemPtr(get_elem_ptr) => {
                        let (base_reg, base_codes) = table.get_absolute_location(get_elem_ptr.src());
                        let (index_reg, index_codes) =
                            table.want_to_visit_value(get_elem_ptr.index(), true, None);
                        codes.extend(base_codes);
                        codes.extend(index_codes);
                        let elem_size = match self.dfg().value(get_elem_ptr.src()).ty().kind() {
                            TypeKind::Pointer(base) => match base.kind() {
                                TypeKind::Array(elem, _) => elem.size(),
                                _ => {
                                    return Err("getelemptr source must point to an array. ".to_string())
                                }
                            },
                            _ => return Err("getelemptr source must be a pointer. ".to_string()),
                        };
                        if elem_size != 1 {
                            codes.push(format!("  li\t{}, {}", REGISTER_NAMES[REG_X31], elem_size));
                            codes.push(format!(
                                "  mul\t{}, {}, {}",
                                REGISTER_NAMES[REG_X31],
                                REGISTER_NAMES[index_reg],
                                REGISTER_NAMES[REG_X31]
                            ));
                            codes.push(format!(
                                "  add\t{}, {}, {}",
                                REGISTER_NAMES[base_reg],
                                REGISTER_NAMES[base_reg],
                                REGISTER_NAMES[REG_X31]
                            ));
                        } else {
                            codes.push(format!(
                                "  add\t{}, {}, {}",
                                REGISTER_NAMES[base_reg],
                                REGISTER_NAMES[base_reg],
                                REGISTER_NAMES[index_reg]
                            ));
                        }
                        table.__update_user(base_reg, value);
                        codes.extend(table.save_register(base_reg));
                        table.clear_registers();
                    }
                    _ => return Err("Unsupported Koopa instruction kind. ".to_string()),
                }
            }
        }

        codes.push(format!("{}:", return_label));
        if has_call {
            codes.extend(table.load_with_offset(REG_RA, ra_offset as isize));
        }
        if frame_size > 0 {
            codes.extend(adjust_sp(frame_size as isize));
        }
        codes.push("  ret".to_string());
        Ok(codes)
    }
}

